/**
 * Small pieces the agents and voice scenes share, each ported from the app
 * component named on it: a Select's trigger, the device OS icon, a textarea
 * that grows with its text, and Settings (src/panels/SettingsHub.tsx) open
 * over a window.
 */
import { useLayoutEffect, type CSSProperties, type ReactNode, type RefObject } from "react";
import { ChevronDown } from "lucide-react";
import { Shot } from "../../home/Chrome";
import type { BackdropScene } from "../../home/Backdrop";
import { AppWindow, WIN_SIZE } from "../../home/Scenes";
import { SETTINGS_VIEW, SETTINGS_WINDOW_BOX, SettingsCanvas, SettingsHubDialog, type SettingsSectionId } from "../settings/SettingsWindow";

/* ------------------------------------------------------------- select -- */

/**
 * The closed trigger of the app's Select (src/ui/Select.tsx): the chosen
 * option's icon and label and the chevron. The scenes show the choice made,
 * so the button opens nothing.
 */
export function SelectButton({
  icon,
  label,
  ariaLabel,
  className = "",
  title,
  disabled,
}: {
  icon?: ReactNode;
  label: string;
  ariaLabel?: string;
  className?: string;
  title?: string;
  disabled?: boolean;
}) {
  return (
    <button
      type="button"
      className={`cselect ${className}`}
      disabled={disabled}
      aria-label={ariaLabel}
      aria-haspopup="listbox"
      aria-expanded={false}
      title={title}
    >
      {icon}
      <span className="cselect-value">{label}</span>
      <ChevronDown size={14} className="muted-icon" />
    </button>
  );
}

