/* ----------------------------------------------------------- textarea -- */

/**
 * The app's useAutoGrow (src/ui/useAutoGrow.ts): the textarea is as tall as
 * its text, between `minLines` and `maxLines` lines.
 */
export function useAutoGrow(ref: RefObject<HTMLTextAreaElement>, value: string, { minLines = 1, maxLines = 6 } = {}) {
  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    const style = getComputedStyle(element);
    const line = parseFloat(style.lineHeight) || parseFloat(style.fontSize) * 1.45 || 18;
    const chrome = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom) + parseFloat(style.borderTopWidth) + parseFloat(style.borderBottomWidth);
    const min = line * minLines + chrome;
    const max = line * maxLines + chrome;
    element.style.height = "auto";
    const height = value ? Math.min(Math.max(element.scrollHeight, min), max) : min;
    element.style.height = `${Math.ceil(height)}px`;
    element.style.overflowY = element.scrollHeight > max + 1 ? "auto" : "hidden";
  }, [ref, value, minLines, maxLines]);
}

/* ----------------------------------------------------------- settings -- */

/**
 * Settings open over the window, using the settings scenes' dialog and
 * framing (components/docs/settings/SettingsWindow.tsx), with `overlay` on
 * top: a menu or confirmation the page opened, placed against the window as
 * the app's portals are against its viewport. A page that opens a menu past
 * the dialog's edge sets the card's `bottom` (window pixels) lower.
 */
export function SettingsScene({
  backdrop,
  section,
  page,
  bottom = SETTINGS_VIEW.bottom,
  overlay,
  children,
}: {
  backdrop: BackdropScene;
  section: SettingsSectionId;
  page: string;
  bottom?: number;
  overlay?: ReactNode;
  children: ReactNode;
}) {
  // The app's viewport units, sized to this window (see scripts/sync-app-css.mjs).
  const viewport = { display: "contents", "--pz-vh": `${WIN_SIZE.height / 100}px`, "--pz-vw": `${WIN_SIZE.width / 100}px` } as CSSProperties;
  return (
    <Shot id={backdrop} width={SETTINGS_VIEW.right - SETTINGS_VIEW.left} height={bottom - SETTINGS_VIEW.top}>
      <AppWindow box={SETTINGS_WINDOW_BOX}>
        <SettingsCanvas />
        <SettingsHubDialog section={section} page={page}>
          {children}
        </SettingsHubDialog>
        {overlay ? <div style={viewport}>{overlay}</div> : null}
      </AppWindow>
    </Shot>
  );
}
